/*
    Dashboard Tổng quan — DASH_Overview_GetFilter
    Lấy danh sách Năm học / Khoa / Khóa

    @ScienceID — tuỳ chọn, lọc khóa
    @ListType  — 0 = Năm học, 1 = Khoa, 2 = Khóa
*/

IF OBJECT_ID(N'dbo.DASH_Overview_GetFilter', N'P') IS NOT NULL
    DROP PROCEDURE dbo.DASH_Overview_GetFilter;
GO

CREATE PROCEDURE dbo.DASH_Overview_GetFilter
(
    @ScienceID nvarchar(50) = NULL,
    @ListType tinyint
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @ListType = 0
    BEGIN
        Select
            SIM_Year.YearID,
            SIM_Year.YearName
        From SIM_Year
        Where SIM_Year.IsActived = 1
        Order by SIM_Year.YearID Desc;
        RETURN;
    END

    IF @ListType = 1
    BEGIN
        Exec dbo.DASH_StudentClassSize_GetFilter
            @ScienceID = @ScienceID,
            @CourseID = NULL,
            @ListType = 1;
        RETURN;
    END

    IF @ListType = 2
    BEGIN
        Exec dbo.DASH_StudentClassSize_GetFilter
            @ScienceID = @ScienceID,
            @CourseID = NULL,
            @ListType = 2;
        RETURN;
    END
END
GO

/*
    Ví dụ test:
    Exec dbo.DASH_Overview_GetFilter @ListType = 0;
    Exec dbo.DASH_Overview_GetFilter @ListType = 1;
    Exec dbo.DASH_Overview_GetFilter @ListType = 2, @ScienceID = NULL;
*/

using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Text;
using System.Web;
using System.Web.Script.Serialization;
using System.Web.SessionState;
using SimsObject;

namespace InformationWeb.Dashboards.API
{
    /// <summary>
    /// API JSON dashboard tổng quan (/bang-dieu-khien.html).
    /// action=filters — Năm học / Khoa / Khóa
    /// action=data    — KPI, biểu đồ, cảnh báo, insight
    /// </summary>
    public class HomeDashboardApi : IHttpHandler, IReadOnlySessionState
    {
        private const string PERMISSION_VIEW = "frmWebStudentList_View";
        private const string SP_DATA = "DASH_Overview_GetData";
        private const string SP_FILTER = "DASH_Overview_GetFilter";

        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json";
            context.Response.ContentEncoding = Encoding.UTF8;

            if (WebGlobal.User == null)
            {
                WriteJson(context, false, "Bạn chưa đăng nhập hệ thống.", null);
                return;
            }

            if (!WebGlobal.HasPermission(PERMISSION_VIEW))
            {
                WriteJson(context, false, "Bạn không có quyền xem bảng điều khiển.", null);
                return;
            }

            try
            {
                string strAction = GetRequestValue(context, "action");
                if (strAction != null && strAction.ToLower() == "filters")
                    HandleFilters(context);
                else
                    HandleData(context);
            }
            catch (Exception)
            {
                WriteJson(context, false, "Có lỗi xảy ra khi tải dữ liệu dashboard.", null);
            }
        }

        private void HandleFilters(HttpContext context)
        {
            string strListType = GetRequestValue(context, "listType");
            string strScienceId = GetRequestValue(context, "scienceId");

            if (strListType == null || strListType == "")
            {
                WriteJson(context, false, "Thiếu loại danh sách lọc.", null);
                return;
            }

            byte byListType = Convert.ToByte(strListType);
            SIM_Class objClass = new SIM_Class();
            DataTable dtbItems = objClass.GetDataTable(
                SP_FILTER,
                "@ScienceID", NormalizeFilter(strScienceId),
                "@ListType", byListType);

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["items"] = DataTableToList(dtbItems);

            WriteJson(context, true, "", dicData);
        }

        private void HandleData(HttpContext context)
        {
            string strYearId = GetRequestValue(context, "yearId");
            string strSemester = GetRequestValue(context, "semester");
            string strScienceId = GetRequestValue(context, "scienceId");
            string strCourseId = GetRequestValue(context, "courseId");

            object objYearId = DBNull.Value;
            object objSemester = DBNull.Value;

            if (strYearId != null && strYearId.Trim() != "" && strYearId != "0")
                objYearId = Convert.ToInt32(strYearId);

            if (strSemester != null && strSemester.Trim() != "" && strSemester != "0" && strSemester != "-1")
                objSemester = Convert.ToByte(strSemester);

            Dictionary<string, DataTable> dicTables = GetDashboardData(
                objYearId,
                objSemester,
                strScienceId,
                strCourseId);

            if (dicTables["kpi"] == null)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["kpi"] = BuildKpi(dicTables["kpi"]);
            dicData["byScience"] = DataTableToList(dicTables["byScience"]);
            dicData["enrollmentByMonth"] = DataTableToList(dicTables["enrollmentByMonth"]);
            dicData["graduationByYear"] = DataTableToList(dicTables["graduationByYear"]);
            dicData["studyResultByScience"] = DataTableToList(dicTables["studyResultByScience"]);
            dicData["revenueByMonth"] = DataTableToList(dicTables["revenueByMonth"]);
            dicData["feeRate"] = DataTableToList(dicTables["feeRate"]);
            dicData["teachingLoadByScience"] = DataTableToList(dicTables["teachingLoadByScience"]);
            dicData["teachingHoursByMonth"] = DataTableToList(dicTables["teachingHoursByMonth"]);
            dicData["libraryByMonth"] = DataTableToList(dicTables["libraryByMonth"]);
            dicData["topBooks"] = DataTableToList(dicTables["topBooks"]);
            dicData["alerts"] = DataTableToList(dicTables["alerts"]);
            dicData["insights"] = BuildInsights(dicTables);
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");

            WriteJson(context, true, "", dicData);
        }

        private Dictionary<string, object> BuildKpi(DataTable dtbKpi)
        {
            Dictionary<string, object> dicKpi = new Dictionary<string, object>();

            if (dtbKpi == null || dtbKpi.Rows.Count == 0)
                return dicKpi;

            DataRow drw = dtbKpi.Rows[0];
            int intTotalStudent = GetRowInt(drw, "TotalStudent");
            int intStudying = GetRowInt(drw, "StudyingStudent");
            int intTeachers = GetRowInt(drw, "TotalTeacher");
            int intClasses = GetRowInt(drw, "TotalClass");
            decimal decGradRate = GetRowDecimal(drw, "GraduationRate");
            int intWarning = GetRowInt(drw, "WarningStudent");
            decimal decDebt = GetRowDecimal(drw, "TotalDebtMoney");
            int intDebtStudent = GetRowInt(drw, "DebtStudentCount");
            decimal decFeeRate = GetRowDecimal(drw, "FeeRate");
            int intBooks = GetRowInt(drw, "TotalBooks");

            dicKpi["students"] = BuildKpiItem(FormatNumber(intTotalStudent), "neutral", "", "sinh viên trong hệ thống");
            dicKpi["teachers"] = BuildKpiItem(FormatNumber(intTeachers), "neutral", "", "giáo viên đang hoạt động");
            dicKpi["classes"] = BuildKpiItem(FormatNumber(intClasses), "neutral", "", "lớp đang mở");
            dicKpi["graduation"] = BuildKpiItem(decGradRate.ToString("0.0") + "%", "neutral", "", "tỷ lệ tốt nghiệp / đang học");
            dicKpi["warning"] = BuildKpiItem(FormatNumber(intWarning), intWarning > 0 ? "down" : "neutral", "", "SV cảnh báo / nghỉ học");
            dicKpi["debt"] = BuildKpiItem(FormatMoneyShort(decDebt), intDebtStudent > 0 ? "up" : "neutral", "", intDebtStudent + " SV còn nợ");
            dicKpi["feeRate"] = BuildKpiItem(decFeeRate.ToString("0.0") + "%", "neutral", "", "SV đang học không nợ học phí");
            dicKpi["books"] = BuildKpiItem(FormatNumber(intBooks), "neutral", "", "đầu sách thư viện");

            return dicKpi;
        }

        private Dictionary<string, object> BuildKpiItem(string value, string trend, string change, string note)
        {
            Dictionary<string, object> dicItem = new Dictionary<string, object>();
            dicItem["value"] = value;
            dicItem["trend"] = trend;
            dicItem["change"] = change;
            dicItem["note"] = note;
            return dicItem;
        }

        private List<Dictionary<string, object>> BuildInsights(Dictionary<string, DataTable> dicTables)
        {
            List<Dictionary<string, object>> lstInsights = new List<Dictionary<string, object>>();

            DataTable dtbKpi = dicTables["kpi"];
            DataTable dtbScience = dicTables["byScience"];
            DataTable dtbAlerts = dicTables["alerts"];

            if (dtbKpi != null && dtbKpi.Rows.Count > 0)
            {
                DataRow drw = dtbKpi.Rows[0];
                int intDebtStudent = GetRowInt(drw, "DebtStudentCount");
                decimal decDebt = GetRowDecimal(drw, "TotalDebtMoney");
                if (intDebtStudent > 0)
                {
                    lstInsights.Add(BuildInsight(String.Format(
                        "Có <strong>{0} sinh viên</strong> còn công nợ học phí, tổng nợ <strong>{1}</strong>.",
                        intDebtStudent,
                        FormatMoneyShort(decDebt))));
                }

                decimal decGradRate = GetRowDecimal(drw, "GraduationRate");
                if (decGradRate > 0)
                {
                    lstInsights.Add(BuildInsight(String.Format(
                        "Tỷ lệ tốt nghiệp hiện tại đạt <strong>{0}%</strong> trên tổng sinh viên đang học và đã tốt nghiệp.",
                        decGradRate.ToString("0.0"))));
                }
            }

            if (dtbScience != null && dtbScience.Rows.Count > 0)
            {
                DataRow drwTop = dtbScience.Rows[0];
                int intMax = 0;
                int intRow;
                for (intRow = 0; intRow < dtbScience.Rows.Count; intRow++)
                {
                    int intCount = GetRowInt(dtbScience.Rows[intRow], "StudentCount");
                    if (intCount > intMax)
                    {
                        intMax = intCount;
                        drwTop = dtbScience.Rows[intRow];
                    }
                }
                string strScienceName = GetRowString(drwTop, "ScienceName");
                if (strScienceName != "")
                {
                    lstInsights.Add(BuildInsight(String.Format(
                        "Khoa <strong>{0}</strong> có sĩ số cao nhất với <strong>{1} sinh viên</strong>.",
                        strScienceName,
                        FormatNumber(intMax))));
                }
            }

            if (dtbAlerts != null)
            {
                int intRow;
                for (intRow = 0; intRow < dtbAlerts.Rows.Count; intRow++)
                {
                    string strText = GetRowString(dtbAlerts.Rows[intRow], "AlertText");
                    if (strText != "")
                        lstInsights.Add(BuildInsight(strText));
                }
            }

            if (lstInsights.Count == 0)
            {
                lstInsights.Add(BuildInsight("Dữ liệu hệ thống đã được tải. Chưa phát hiện cảnh báo nghiêm trọng."));
            }

            return lstInsights;
        }

        private Dictionary<string, object> BuildInsight(string htmlText)
        {
            Dictionary<string, object> dicRow = new Dictionary<string, object>();
            dicRow["text"] = htmlText;
            return dicRow;
        }

        private Dictionary<string, DataTable> GetDashboardData(
            object yearId,
            object semester,
            string scienceId,
            string courseId)
        {
            Dictionary<string, DataTable> dicResult = new Dictionary<string, DataTable>();
            SIM_Class objClass = new SIM_Class();

            dicResult["kpi"] = CallResultSet(objClass, yearId, semester, scienceId, courseId, 1);
            dicResult["byScience"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 2);
            dicResult["enrollmentByMonth"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 3);
            dicResult["graduationByYear"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 4);
            dicResult["studyResultByScience"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 5);
            dicResult["revenueByMonth"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 6);
            dicResult["feeRate"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 7);
            dicResult["teachingLoadByScience"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 8);
            dicResult["teachingHoursByMonth"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 9);
            dicResult["libraryByMonth"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 10);
            dicResult["topBooks"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 11);
            dicResult["alerts"] = CallResultSetSafe(objClass, yearId, semester, scienceId, courseId, 12);

            return dicResult;
        }

        private DataTable CallResultSet(
            SIM_Class objClass,
            object yearId,
            object semester,
            string scienceId,
            string courseId,
            byte resultSet)
        {
            return objClass.GetDataTable(
                SP_DATA,
                "@YearID", yearId,
                "@Semester", semester,
                "@ScienceID", NormalizeFilter(scienceId),
                "@CourseID", NormalizeFilter(courseId),
                "@ResultSet", resultSet);
        }

        private DataTable CallResultSetSafe(
            SIM_Class objClass,
            object yearId,
            object semester,
            string scienceId,
            string courseId,
            byte resultSet)
        {
            try
            {
                return CallResultSet(objClass, yearId, semester, scienceId, courseId, resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        private int GetRowInt(DataRow drw, string columnName)
        {
            if (drw.Table.Columns.Contains(columnName) == false)
                return 0;
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return 0;
            try
            {
                return Convert.ToInt32(drw[columnName]);
            }
            catch (Exception)
            {
                return 0;
            }
        }

        private decimal GetRowDecimal(DataRow drw, string columnName)
        {
            if (drw.Table.Columns.Contains(columnName) == false)
                return 0;
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return 0;
            try
            {
                return Convert.ToDecimal(drw[columnName]);
            }
            catch (Exception)
            {
                return 0;
            }
        }

        private string GetRowString(DataRow drw, string columnName)
        {
            if (drw.Table.Columns.Contains(columnName) == false)
                return "";
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            return drw[columnName].ToString().Trim();
        }

        private string FormatNumber(int value)
        {
            return value.ToString("#,##0").Replace(",", ".");
        }

        private string FormatMoneyShort(decimal value)
        {
            if (value >= 1000000000m)
                return (value / 1000000000m).ToString("0.#") + " tỷ";
            if (value >= 1000000m)
                return (value / 1000000m).ToString("0.#") + " tr";
            if (value >= 1000m)
                return (value / 1000m).ToString("0.#") + " nghìn";
            return value.ToString("#,##0").Replace(",", ".");
        }

        private List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    if (objValue == DBNull.Value)
                        dicRow[dtb.Columns[intCol].ColumnName] = null;
                    else if (objValue is DateTime)
                        dicRow[dtb.Columns[intCol].ColumnName] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[dtb.Columns[intCol].ColumnName] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            string strBody = ReadRequestBody(context);
            if (strBody == null || strBody == "")
                return null;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            Dictionary<string, object> dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            if (dicBody == null || !dicBody.ContainsKey(key) || dicBody[key] == null)
                return null;

            return Convert.ToString(dicBody[key]);
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            context.Request.InputStream.Position = 0;
            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

/**
* School Dashboard - ApexCharts + API thật
* Load: DASH_Overview_GetData -> HomeDashboardApi.ashx -> ApexCharts
*/
(function () {
    "use strict";

    var API_URL = "/Dashboards/API/HomeDashboardApi.ashx";
    var PRIMARY = "#4b6c9e";
    var PRIMARY_LIGHT = "#6b8bb8";
    var SUCCESS = "#2e9e6e";
    var DANGER = "#d9534f";
    var WARNING = "#e8a838";
    var INFO = "#5b9bd5";
    var MUTED = "#adb0bb";

    var chartInstances = {};
    var lastPayload = null;
    var eventsBound = false;
    var filtersLoaded = false;

    var baseChartOpts = {
        fontFamily: "inherit",
        foreColor: MUTED,
        toolbar: { show: false },
        width: "100%"
    };

    function getEl(id) {
        return document.getElementById(id);
    }

    function getChartResponsive(extra) {
        var rules = [
            {
                breakpoint: 576,
                options: {
                    chart: { height: 250 },
                    legend: { fontSize: "11px" }
                }
            },
            {
                breakpoint: 768,
                options: {
                    chart: { height: 280 }
                }
            }
        ];
        var i;
        if (extra && extra.length) {
            for (i = 0; i < extra.length; i++) {
                rules.push(extra[i]);
            }
        }
        return rules;
    }

    function resizeAllCharts() {
        var key;
        for (key in chartInstances) {
            if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                chartInstances[key].windowResizeHandler();
            }
        }
    }

    function formatNumber(val) {
        var num = parseInt(val, 10);
        if (isNaN(num)) {
            return "0";
        }
        return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function destroyCharts() {
        var key;
        for (key in chartInstances) {
            if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                chartInstances[key].destroy();
                chartInstances[key] = null;
            }
        }
    }

    function renderChart(id, options) {
        var el = document.querySelector(id);
        if (!el) {
            return;
        }
        if (typeof ApexCharts === "undefined") {
            return;
        }
        if (chartInstances[id]) {
            chartInstances[id].destroy();
        }
        if (!options.responsive) {
            options.responsive = getChartResponsive();
        }
        chartInstances[id] = new ApexCharts(el, options);
        chartInstances[id].render();
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function showState(state) {
        var loading = getEl("schDashStateLoading");
        var error = getEl("schDashStateError");
        var content = getEl("schDashContent");
        if (loading) {
            loading.className = state === "loading" ? "sch-dash-state" : "sch-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "sch-dash-state" : "sch-dash-state d-none";
        }
        if (content) {
            content.style.display = state === "ready" ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("schDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function getFilterValue(id) {
        var el = getEl(id);
        return el ? el.value : "";
    }

    function readFilters() {
        return {
            yearId: getFilterValue("schDashFilterYear"),
            semester: getFilterValue("schDashFilterSemester"),
            scienceId: getFilterValue("schDashFilterFaculty"),
            courseId: getFilterValue("schDashFilterCourse")
        };
    }

    function fillSelect(id, rows, valueField, textField, defaultLabel, defaultValue) {
        var el = getEl(id);
        var i;
        var row;
        if (!el) {
            return;
        }
        while (el.options.length > 0) {
            el.remove(0);
        }
        el.appendChild(new Option(defaultLabel || "--Chọn--", defaultValue || ""));
        if (!rows || !rows.length) {
            return;
        }
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            if (!row || row[valueField] === null || row[valueField] === undefined) {
                continue;
            }
            el.appendChild(new Option(String(row[textField] || row[valueField]), String(row[valueField])));
        }
    }

    function loadFilterList(listType, scienceId, callback) {
        postJson({
            action: "filters",
            listType: listType,
            scienceId: scienceId || ""
        }, callback);
    }

    function loadYears(callback) {
        loadFilterList(0, "", function (ok, msg, data) {
            if (!ok) {
                callback(false, msg);
                return;
            }
            fillSelect("schDashFilterYear", data.items || [], "YearID", "YearName", "--Chọn--", "");
            callback(true, "");
        });
    }

    function loadSciences(callback) {
        loadFilterList(1, "", function (ok, msg, data) {
            if (!ok) {
                callback(false, msg);
                return;
            }
            fillSelect("schDashFilterFaculty", data.items || [], "ScienceID", "ScienceName", "Tất cả khoa", "");
            callback(true, "");
        });
    }

    function loadCourses(scienceId, callback) {
        loadFilterList(2, scienceId || "", function (ok, msg, data) {
            if (!ok) {
                callback(false, msg);
                return;
            }
            fillSelect("schDashFilterCourse", data.items || [], "CourseID", "CourseName", "Tất cả khóa", "");
            callback(true, "");
        });
    }

    function loadAllFilters(done) {
        loadYears(function (okYear, msgYear) {
            if (!okYear) {
                done(false, msgYear);
