    function updateKpiCards(kpi) {
        var data = kpi || {};
        var map = {
            "kpi-students": data.students,
            "kpi-teachers": data.teachers,
            "kpi-classes": data.classes,
            "kpi-graduation": data.graduation,
            "kpi-warning": data.warning,
            "kpi-debt": data.debt,
            "kpi-fee-rate": data.feeRate,
            "kpi-books": data.books
        };
        var key;
        for (key in map) {
            if (!map.hasOwnProperty(key)) {
                continue;
            }
            var card = document.getElementById(key);
            if (!card) {
                continue;
            }
            var item = map[key] || { value: "0", trend: "neutral", change: "", note: "" };
            var valueEl = card.querySelector(".sch-dash-kpi-value");
            var trendEl = card.querySelector(".sch-dash-kpi-trend");
            if (valueEl) {
                valueEl.textContent = item.value || "0";
            }
            if (trendEl) {
                trendEl.className = "sch-dash-kpi-trend " + (item.trend || "neutral");
                if (item.change && item.change !== "") {
                    var icon = item.trend === "up" ? "bi-arrow-up-short" : (item.trend === "down" ? "bi-arrow-down-short" : "bi-dash");
                    trendEl.innerHTML = "<i class=\"bi " + icon + "\"></i> " + item.change + " <span class=\"fw-normal text-muted\">" + (item.note || "") + "</span>";
                } else {
                    trendEl.innerHTML = "<span class=\"fw-normal text-muted\">" + (item.note || "") + "</span>";
                }
            }
        }
    }

