        lastPayload = data || {};
        updateKpiCards(lastPayload.kpi);
        updateTimestamp(lastPayload.updatedAt);
        destroyCharts();
        renderAllCharts(lastPayload);
    }

    function loadDashboardData() {
        var filters = readFilters();
        showState("loading");
        postJson({
            action: "data",
            yearId: filters.yearId,
            semester: filters.semester,
            scienceId: filters.scienceId,
            courseId: filters.courseId
        }, function (ok, msg, data) {
            if (!ok) {
                showState("error");
                setErrorMessage(msg);
                return;
            }
            showState("ready");
            applyPayload(data);
        });
    }

    function loadDashboard() {
        if (!filtersLoaded) {
            loadAllFilters(function (ok, msg) {
                filtersLoaded = true;
                if (!ok) {
                    showState("error");
                    setErrorMessage(msg);
                    return;
                }
                loadDashboardData();
            });
            return;
        }
        loadDashboardData();
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var refreshBtn = getEl("schDashBtnRefresh");
        var facultyEl = getEl("schDashFilterFaculty");
        var filters = document.querySelectorAll(".page-content .sch-dash-filter-select");

        if (refreshBtn) {
            refreshBtn.addEventListener("click", function () {
                refreshBtn.classList.add("is-loading");
                loadDashboardData();
                setTimeout(function () {
                    refreshBtn.classList.remove("is-loading");
                }, 600);
            });
        }

        if (facultyEl) {
            facultyEl.addEventListener("change", function () {
                loadCourses(facultyEl.value, function () {
                    loadDashboardData();
                });
            });
        }

        var i;
        for (i = 0; i < filters.length; i++) {
            if (filters[i].id === "schDashFilterFaculty") {
                continue;
            }
            filters[i].addEventListener("change", function () {
                loadDashboardData();
            });
        }

        var resizeTimer = null;
        window.addEventListener("resize", function () {
            if (resizeTimer) {
                clearTimeout(resizeTimer);
            }
            resizeTimer = setTimeout(function () {
                resizeAllCharts();
            }, 200);
        });
    }

    function initSchoolDashboard() {
        if (!getEl("schDashBtnRefresh")) {
            return;
        }
        bindEvents();
        loadDashboard();
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initSchoolDashboard);
    } else {
        initSchoolDashboard();
    }
})();

